"use client";
import {
  memo,
  useMemo,
  useRef,
  useState,
  useEffect,
  useId,
  type KeyboardEvent,
} from "react";
import { animate, useMotionValue, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { formatValue, useContainerDimensions } from "@/components/charts/_shared";
import { InspectionTooltip } from "@/components/charts/_shared/inspection-tooltip";
import { buildSankey, connectedFlow, SANKEY_COLORS } from "./model";
import { layoutSankey } from "./geometry";
import type {
  SankeyNode,
  SankeyLink,
  SankeyInspection,
  SankeyChartProps,
} from "./types";
export type {
  SankeyNode,
  SankeyLink,
  SankeyInspection,
  SankeyChartProps,
} from "./types";
const placeholderNodes = [
  { id: "start", label: "Entry" },
  { id: "a", label: "Path A" },
  { id: "b", label: "Path B" },
  { id: "end", label: "Complete" },
];
const placeholderLinks = [
  { source: "start", target: "a", value: 60 },
  { source: "start", target: "b", value: 40 },
  { source: "a", target: "end", value: 60 },
  { source: "b", target: "end", value: 40 },
];
const percentage = (value: number, total: number) =>
  total ? (value / total) * 100 : null;
const percent = (n: number | null) => (n === null ? "—" : `${n.toFixed(1)}%`);
function SankeyChartComponent<N extends SankeyNode, L extends SankeyLink>({
  nodes,
  links,
  colors = SANKEY_COLORS,
  align = "justify",
  linkColor = "gradient",
  curvature = 0.5,
  nodeWidth = 18,
  nodeGap = 24,
  showValues = true,
  className,
  height = 400,
  loading = false,
  error = null,
  animation = true,
  valueFormatter = formatValue,
  ariaLabel = "Sankey chart",
  description,
  onNodeClick,
  onLinkClick,
  tooltipRenderer,
}: SankeyChartProps<N, L>) {
  const [rootRef, width] = useContainerDimensions();
  const id = useId();
  const reduced = useReducedMotion();
  const model = useMemo(
    () => buildSankey(nodes, links, colors),
    [nodes, links, colors],
  );
  const placeholder = useMemo(
    () => buildSankey(placeholderNodes, placeholderLinks),
    [],
  );
  const source =
    loading && (!nodes.length || model.error) ? placeholder : model;
  const validHeight = Number.isFinite(height) && height > 0;
  const validWidth =
    Number.isFinite(nodeWidth) && nodeWidth >= 1 && nodeWidth <= 80;
  const validGap = Number.isFinite(nodeGap) && nodeGap >= 0 && nodeGap <= 200;
  const validCurve =
    Number.isFinite(curvature) && curvature >= 0 && curvature <= 1;
  const validAlign = align === "justify" || align === "start";
  const validColor = ["gradient", "source", "target"].includes(linkColor);
  const chartError =
    error ||
    model.error ||
    (!validHeight
      ? "height must be a positive finite number."
      : !validWidth
        ? "nodeWidth must be between 1 and 80 pixels."
        : !validGap
          ? "nodeGap must be between 0 and 200 pixels."
          : !validCurve
            ? "curvature must be between 0 and 1."
            : !validAlign
              ? "align must be justify or start."
              : !validColor
                ? "linkColor must be gradient, source or target."
                : null);
  const frameHeight = validHeight ? height : 400;
  const geometry = useMemo(
    () =>
      layoutSankey(
        source,
        width,
        frameHeight,
        validWidth ? nodeWidth : 18,
        validGap ? nodeGap : 24,
        validCurve ? curvature : 0.5,
        validAlign ? align : "justify",
      ),
    [
      source,
      width,
      frameHeight,
      nodeWidth,
      nodeGap,
      curvature,
      align,
      validWidth,
      validGap,
      validCurve,
      validAlign,
    ],
  );
  const ready = !loading && !chartError && nodes.length > 0 && width > 0;
  const progress = useMotionValue(1);
  const clip = useRef<SVGRectElement>(null);
  useEffect(() => {
    const update = (p: number) =>
      clip.current?.setAttribute("width", String(p * geometry.width));
    update(progress.get());
    return progress.on("change", update);
  }, [progress, geometry.width, ready, loading]);
  useEffect(() => {
    if (!ready || !animation || reduced) {
      progress.jump(1);
      return;
    }
    progress.set(0);
    const controls = animate(progress, 1, {
      duration: 0.85,
      ease: [0.33, 0, 0.2, 1],
    });
    return () => controls.stop();
  }, [ready, animation, reduced, progress]);
  const viewport = useRef<HTMLDivElement>(null);
  const [scroll, setScroll] = useState({ x: 0, y: 0 });
  const [inspection, setInspection] = useState<number | null>(null);
  const [focus, setFocus] = useState<number | null>(null);
  const [tab, setTab] = useState(0);
  const refs = useRef<(SVGElement | null)[]>([]);
  const count = nodes.length + links.length;
  const selected = Math.min(tab, Math.max(0, count - 1));
  useEffect(() => {
    const focused = refs.current.findIndex(
      (element) => element !== null && element === document.activeElement,
    );
    setInspection(focused < 0 ? null : focused);
    setFocus(focused < 0 ? null : focused);
    if (focused >= 0) progress.jump(1);
  }, [nodes, links, loading, error, progress]);
  const active = ready ? inspection : null;
  const activeKind =
    active !== null && active >= nodes.length ? "link" : "node";
  const activeIndex =
    active === null
      ? -1
      : activeKind === "link"
        ? active - nodes.length
        : active;
  const highlighted = useMemo(
    () =>
      active !== null ? connectedFlow(model, activeKind, activeIndex) : null,
    [model, active, activeKind, activeIndex],
  );
  let tip: SankeyInspection<N, L> | null = null;
  let anchor = { x: 0, y: 0 };
  if (active !== null) {
    if (activeKind === "node") {
      const node = model.nodes[activeIndex],
        g = geometry.nodes[activeIndex];
      if (node && g) {
        tip = {
          kind: "node",
          data: node.data,
          index: activeIndex,
          value: node.value,
          incoming: node.incoming,
          outgoing: node.outgoing,
          color: node.color,
        };
        anchor = { x: g.x + g.width / 2, y: g.y + g.height / 2 };
      }
    } else {
      const edge = model.links[activeIndex],
        g = geometry.links[activeIndex];
      if (edge && g) {
        const start = model.nodes[edge.source]!,
          end = model.nodes[edge.target]!;
        tip = {
          kind: "link",
          data: edge.data,
          index: activeIndex,
          source: start.data,
          target: end.data,
          value: edge.value,
          sourcePercentage: percentage(edge.value, start.outgoing),
          targetPercentage: percentage(edge.value, end.incoming),
          color: start.color,
        };
        anchor = { x: g.x, y: g.y };
      }
    }
  }
  const tipX = anchor.x - scroll.x,
    tipY = anchor.y - scroll.y;
  function activate(index: number) {
    setInspection(index);
    if (index < nodes.length) onNodeClick?.(nodes[index]!, index);
    else onLinkClick?.(links[index - nodes.length]!, index - nodes.length);
  }
  function navigate(event: KeyboardEvent<SVGElement>, index: number) {
    if (event.key === "Escape") {
      event.preventDefault();
      setInspection(null);
      return;
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      activate(index);
      return;
    }
    let next = index;
    if (event.key === "Home") next = 0;
    else if (event.key === "End") next = count - 1;
    else if (["ArrowRight", "ArrowDown"].includes(event.key))
      next = (index + 1) % count;
    else if (["ArrowLeft", "ArrowUp"].includes(event.key))
      next = (index - 1 + count) % count;
    else return;
    event.preventDefault();
    setTab(next);
    refs.current[next]?.focus();
  }
  const interactions = (index: number) => ({
    tabIndex: index === selected ? 0 : -1,
    onMouseEnter: () => setInspection(index),
    onPointerDown: () => setInspection(index),
    onFocus: () => {
      setTab(index);
      setFocus(index);
      setInspection(index);
    },
    onClick: () => activate(index),
    onKeyDown: (event: KeyboardEvent<SVGElement>) => navigate(event, index),
    "aria-describedby": active === index ? `${id}-tooltip` : undefined,
  });
  const message =
    !loading && chartError
      ? chartError
      : !loading && !nodes.length
        ? "No Data"
        : !loading && !width
          ? "Waiting for chart space"
          : null;
  return (
    <div
      ref={rootRef}
      className={cn("relative w-full", className)}
      style={{ height: frameHeight }}
      aria-busy={loading}
      onPointerLeave={(event) => {
        if (event.pointerType !== "touch") setInspection(focus);
      }}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setFocus(null);
          setInspection(null);
        }
      }}
    >
      {loading && (
        <span role="status" className="sr-only">
          Loading flow
        </span>
      )}
      {message ? (
        <div
          role={chartError ? "alert" : "status"}
          className="flex h-full items-center justify-center p-6 text-center"
        >
          <div>
            <p
              className={cn(
                "font-medium",
                chartError ? "text-destructive" : "text-muted-foreground",
              )}
            >
              {chartError ? "Chart Error" : message}
            </p>
            {chartError && (
              <p className="mt-2 text-sm text-muted-foreground">{chartError}</p>
            )}
          </div>
        </div>
      ) : (
        <>
          <div
            ref={viewport}
            className="h-full overflow-auto"
            onScroll={(event) =>
              setScroll({
                x: event.currentTarget.scrollLeft,
                y: event.currentTarget.scrollTop,
              })
            }
          >
            <svg
              width={geometry.width}
              height={geometry.height}
              role={loading ? "presentation" : "group"}
              aria-hidden={loading || undefined}
              aria-label={ariaLabel}
              aria-describedby={`${id}-description`}
              onFocusCapture={() => progress.jump(1)}
            >
              <desc id={`${id}-description`}>
                {description ? `${description} ` : ""}Directed flow from left to
                right. Link thickness represents supplied volume. Node height
                represents the larger of incoming and outgoing totals; these
                totals do not imply unique users. Arrow keys inspect nodes then
                links in input order, Home/End jump, Escape dismisses,
                Enter/Space selects. Crowded graphs scroll.
              </desc>
              <defs>
                <clipPath id={`${id}-reveal`} clipPathUnits="userSpaceOnUse">
                  <rect
                    ref={clip}
                    width={geometry.width * progress.get()}
                    height={geometry.height}
                  />
                </clipPath>
                {source.links.map((edge, i) => {
                  const g = geometry.links[i]!;
                  return (
                    <linearGradient
                      key={i}
                      id={`${id}-link-${i}`}
                      gradientUnits="userSpaceOnUse"
                      x1={g.x0}
                      x2={g.x1}
                      y1={g.y0}
                      y2={g.y1}
                    >
                      <stop
                        offset="0%"
                        stopColor={source.nodes[edge.source]!.color}
                      />
                      <stop
                        offset="100%"
                        stopColor={source.nodes[edge.target]!.color}
                      />
                    </linearGradient>
                  );
                })}
              </defs>
              <g
                clipPath={`url(#${id}-reveal)`}
                className={cn(
                  loading && "text-muted",
                  loading &&
                    animation &&
                    !reduced &&
                    "animate-pulse motion-reduce:animate-none",
                )}
              >
                {source.links.map((edge, i) => (
                  <path
                    key={i}
                    data-sankey-link={loading ? undefined : i}
                    data-loading-link={loading ? i : undefined}
                    d={geometry.links[i]!.path}
                    aria-hidden="true"
                    fill={
                      loading
                        ? "currentColor"
                        : linkColor === "gradient"
                          ? `url(#${id}-link-${i})`
                          : source.nodes[
                              linkColor === "target" ? edge.target : edge.source
                            ]!.color
                    }
                    fillOpacity={
                      highlighted
                        ? highlighted.links.has(i)
                          ? 0.65
                          : 0.09
                        : 0.3
                    }
                  />
                ))}
                {source.nodes.map((node, i) => {
                  const g = geometry.nodes[i]!;
                  return (
                    <rect
                      key={i}
                      data-sankey-node={loading ? undefined : i}
                      data-loading-node={loading ? i : undefined}
                      x={g.x}
                      y={g.y}
                      width={g.width}
                      height={g.height}
                      rx={Math.min(3, g.height / 2)}
                      fill={loading ? "currentColor" : node.color}
                      fillOpacity={
                        highlighted && !highlighted.nodes.has(i) ? 0.25 : 1
                      }
                      aria-hidden="true"
                    />
                  );
                })}
              </g>
              {ready &&
                model.links.map((edge, i) => (
                  <path
                    key={i}
                    ref={(node) => {
                      refs.current[nodes.length + i] = node;
                    }}
                    data-sankey-link-target={i}
                    d={geometry.links[i]!.centerPath}
                    fill="none"
                    stroke={
                      focus === nodes.length + i
                        ? "currentColor"
                        : "transparent"
                    }
                    strokeWidth={Math.max(10, geometry.links[i]!.width)}
                    strokeOpacity={0}
                    className={cn(
                      "text-foreground",
                      "outline-none touch-manipulation",
                      onLinkClick ? "cursor-pointer" : "cursor-default",
                    )}
                    role={onLinkClick ? "button" : "graphics-symbol"}
                    aria-label={`${model.nodes[edge.source]!.label} to ${model.nodes[edge.target]!.label}: ${valueFormatter(edge.value)}; ${percent(percentage(edge.value, model.nodes[edge.source]!.outgoing))} of source outgoing`}
                    {...interactions(nodes.length + i)}
                  />
                ))}
              {ready &&
                focus !== null &&
                focus >= nodes.length &&
                geometry.links[focus - nodes.length] && (
                  <path
                    d={geometry.links[focus - nodes.length]!.centerPath}
                    fill="none"
                    strokeWidth={2}
                    pointerEvents="none"
                    aria-hidden="true"
                    className="stroke-foreground"
                  />
                )}
              {source.nodes.map((node, i) => {
                const g = geometry.nodes[i]!;
                return (
                  <g key={i}>
                    <foreignObject
                      x={g.labelX}
                      y={g.labelY}
                      width={g.labelWidth}
                      height={40}
                      aria-hidden="true"
                      pointerEvents="none"
                    >
                      <div
                        className={cn(
                          "w-fit max-w-full rounded-sm bg-background/95 px-1.5 py-0.5",
                          g.last && "ml-auto text-right",
                        )}
                        title={loading ? undefined : node.label}
                      >
                        {loading ? (
                          <span className="inline-block h-2 w-16 rounded bg-muted" />
                        ) : (
                          <>
                            <p className="truncate text-xs font-medium text-foreground">
                              {node.label}
                            </p>
                            {showValues && (
                              <p className="truncate text-[11px] tabular-nums text-muted-foreground">
                                {valueFormatter(node.value)}
                              </p>
                            )}
                          </>
                        )}
                      </div>
                    </foreignObject>
                    {ready && (active === i || focus === i) && (
                      <rect
                        x={g.x - 4}
                        y={g.y + g.height / 2 - Math.max(16, g.height + 8) / 2}
                        width={g.width + 8}
                        height={Math.max(16, g.height + 8)}
                        rx={4}
                        fill="none"
                        strokeWidth={1.5}
                        pointerEvents="none"
                        aria-hidden="true"
                        className="stroke-foreground"
                      />
                    )}
                    {ready && (
                      <path
                        ref={(element) => {
                          refs.current[i] = element;
                        }}
                        data-sankey-node-target={i}
                        d={`M ${g.x - Math.max(6, (44 - g.width) / 2)} ${g.y + g.height / 2 - Math.max(32, g.height + 8) / 2} h ${Math.max(44, g.width + 12)} v ${Math.max(32, g.height + 8)} h ${-Math.max(44, g.width + 12)} Z M ${g.labelX} ${g.labelY} h ${g.labelWidth} v 40 h ${-g.labelWidth} Z`}
                        fill="transparent"
                        className={cn(
                          "outline-none touch-manipulation",
                          onNodeClick ? "cursor-pointer" : "cursor-default",
                        )}
                        role={onNodeClick ? "button" : "graphics-symbol"}
                        aria-label={`${node.label}: ${valueFormatter(node.value)} volume; ${valueFormatter(node.incoming)} incoming; ${valueFormatter(node.outgoing)} outgoing`}
                        {...interactions(i)}
                      />
                    )}
                  </g>
                );
              })}
            </svg>
          </div>
          {ready && (
            <table className="sr-only">
              <caption>{ariaLabel} source connections</caption>
              <thead>
                <tr>
                  <th scope="col">Source</th>
                  <th scope="col">Target</th>
                  <th scope="col">Volume</th>
                </tr>
              </thead>
              <tbody>
                {model.links.map((edge) => (
                  <tr key={edge.index}>
                    <td>{model.nodes[edge.source]!.label}</td>
                    <td>{model.nodes[edge.target]!.label}</td>
                    <td>{valueFormatter(edge.value)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          {tip && (
            <InspectionTooltip
              id={`${id}-tooltip`}
              x={tipX}
              y={tipY}
              width={width}
              height={frameHeight}
            >
              {tooltipRenderer ? (
                tooltipRenderer(tip)
              ) : (
                <>
                  <p className="mb-2 border-b border-border pb-2 text-xs font-medium text-muted-foreground">
                    {tip.kind === "node"
                      ? tip.data.label
                      : `${tip.source.label} → ${tip.target.label}`}
                  </p>
                  <div className="flex items-center justify-between gap-6 text-sm font-semibold">
                    <span
                      className="size-2.5 rounded-sm"
                      style={{ background: tip.color }}
                    />
                    <span>{valueFormatter(tip.value)}</span>
                  </div>
                  {tip.kind === "node" ? (
                    <>
                      <p className="mt-2 text-xs text-muted-foreground">
                        {valueFormatter(tip.incoming)} incoming
                      </p>
                      <p className="mt-1 text-xs text-muted-foreground">
                        {valueFormatter(tip.outgoing)} outgoing
                      </p>
                    </>
                  ) : (
                    <>
                      <p className="mt-2 text-xs text-muted-foreground">
                        {percent(tip.sourcePercentage)} of source outgoing
                      </p>
                      <p className="mt-1 text-xs text-muted-foreground">
                        {percent(tip.targetPercentage)} of target incoming
                      </p>
                    </>
                  )}
                </>
              )}
            </InspectionTooltip>
          )}
        </>
      )}
    </div>
  );
}
export const SankeyChart = memo(
  SankeyChartComponent,
) as typeof SankeyChartComponent;

import type { ReactNode } from "react";
/** IDs identify occurrences, so the same event can appear at different steps. */
export interface SankeyNode {
  readonly id: string;
  readonly label: string;
  readonly color?: string;
}
/** An aggregated directed transition. Use consistent units across all links. */
export interface SankeyLink {
  readonly source: string;
  readonly target: string;
  readonly value: number;
}
export type SankeyInspection<
  N extends SankeyNode = SankeyNode,
  L extends SankeyLink = SankeyLink,
> =
  | {
      readonly kind: "node";
      readonly data: N;
      readonly index: number;
      readonly value: number;
      readonly incoming: number;
      readonly outgoing: number;
      readonly color: string;
    }
  | {
      readonly kind: "link";
      readonly data: L;
      readonly index: number;
      readonly source: N;
      readonly target: N;
      readonly value: number;
      readonly sourcePercentage: number | null;
      readonly targetPercentage: number | null;
      readonly color: string;
    };
export interface SankeyChartProps<
  N extends SankeyNode = SankeyNode,
  L extends SankeyLink = SankeyLink,
> {
  /** Unique IDs, display labels and optional CSS colors. Input order orders peers. */
  readonly nodes: readonly N[];
  /** Finite nonnegative volumes. Cycles and references to absent IDs are errors. */
  readonly links: readonly L[];
  readonly colors?: readonly string[];
  /** Align terminal nodes to the last column, or keep their earliest depth. */
  readonly align?: "justify" | "start";
  readonly linkColor?: "gradient" | "source" | "target";
  /** Horizontal curve tension from 0 (straight) to 1. */
  readonly curvature?: number;
  readonly nodeWidth?: number;
  readonly nodeGap?: number;
  readonly showValues?: boolean;
  readonly className?: string;
  /** A stable frame; crowded graphs scroll inside it. */
  readonly height?: number;
  readonly loading?: boolean;
  readonly error?: string | null;
  readonly animation?: boolean;
  readonly valueFormatter?: (value: number) => string;
  readonly ariaLabel?: string;
  readonly description?: string;
  readonly onNodeClick?: (node: N, index: number) => void;
  readonly onLinkClick?: (link: L, index: number) => void;
  readonly tooltipRenderer?: (inspection: SankeyInspection<N, L>) => ReactNode;
}

import type { SankeyNode, SankeyLink } from "./types";
export const SANKEY_COLORS = [
  "#3b82f6",
  "#8b5cf6",
  "#06b6d4",
  "#10b981",
  "#f59e0b",
  "#ec4899",
] as const;
export interface FlowNode<N> {
  data: N;
  index: number;
  label: string;
  color: string;
  incoming: number;
  outgoing: number;
  value: number;
  depth: number;
  sources: number[];
  targets: number[];
}
export interface FlowLink<L> {
  data: L;
  index: number;
  source: number;
  target: number;
  value: number;
}
export interface FlowModel<N, L> {
  nodes: FlowNode<N>[];
  links: FlowLink<L>[];
  depth: number;
  error: string | null;
}
export function buildSankey<N extends SankeyNode, L extends SankeyLink>(
  nodes: readonly N[],
  links: readonly L[],
  colors: readonly string[] = SANKEY_COLORS,
): FlowModel<N, L> {
  const fail = (error: string): FlowModel<N, L> => ({
    nodes: [],
    links: [],
    depth: 0,
    error,
  });
  if (colors.some((c) => typeof c !== "string" || !c.trim()))
    return fail("colors must contain nonempty CSS colors.");
  const palette = colors.length ? colors : SANKEY_COLORS;
  const ids = new Map<string, number>();
  for (const [index, node] of nodes.entries()) {
    if (typeof node.id !== "string" || !node.id.trim())
      return fail(`Node ${index + 1}: provide a nonempty string id.`);
    if (ids.has(node.id))
      return fail(
        `Duplicate node id "${node.id}". Give each occurrence its own ID.`,
      );
    if (typeof node.label !== "string" || !node.label.trim())
      return fail(`Node "${node.id}": provide a nonempty label.`);
    if (
      node.color !== undefined &&
      (typeof node.color !== "string" || !node.color.trim())
    )
      return fail(`Node "${node.id}": color must be a nonempty CSS color.`);
    ids.set(node.id, index);
  }
  const result: FlowNode<N>[] = nodes.map((node, index) => ({
    data: node,
    index,
    label: node.label,
    color: node.color ?? palette[index % palette.length]!,
    incoming: 0,
    outgoing: 0,
    value: 0,
    depth: 0,
    sources: [],
    targets: [],
  }));
  const edges: FlowLink<L>[] = [];
  for (const [index, link] of links.entries()) {
    const source = ids.get(link.source),
      target = ids.get(link.target);
    if (source === undefined || target === undefined)
      return fail(
        `Link ${index + 1}: source "${link.source}" and target "${link.target}" must reference existing node IDs.`,
      );
    if (
      typeof link.value !== "number" ||
      !Number.isFinite(link.value) ||
      link.value < 0
    )
      return fail(
        `Link ${index + 1}: value must be a finite nonnegative number.`,
      );
    if (source === target)
      return fail(
        `Link ${index + 1}: self-links are cycles. Use separate IDs for repeated steps.`,
      );
    result[source]!.outgoing += link.value;
    result[target]!.incoming += link.value;
    if (
      !Number.isFinite(result[source]!.outgoing) ||
      !Number.isFinite(result[target]!.incoming)
    )
      return fail(
        `Link ${index + 1}: node totals exceed the numeric range. Rescale all link values to a consistent unit.`,
      );
    result[source]!.targets.push(index);
    result[target]!.sources.push(index);
    edges.push({ data: link, index, source, target, value: link.value });
  }
  const pending = result.map((n) => n.sources.length);
  const queue = result.filter((n) => !n.sources.length).map((n) => n.index);
  let depth = 0;
  for (let head = 0; head < queue.length; head++) {
    const node = result[queue[head]!]!;
    for (const edge of node.targets) {
      const target = result[edges[edge]!.target]!;
      target.depth = Math.max(target.depth, node.depth + 1);
      depth = Math.max(depth, target.depth);
      pending[target.index]!--;
      if (!pending[target.index]) queue.push(target.index);
    }
  }
  if (queue.length !== nodes.length)
    return fail(
      "Sankey requires an acyclic graph. Represent a return visit with a new node ID at a later step.",
    );
  for (const node of result)
    node.value = Math.max(node.incoming, node.outgoing);
  return { nodes: result, links: edges, depth, error: null };
}
/** Ancestors and descendants, without inventing individual journeys through merges. */
export function connectedFlow<N, L>(
  model: FlowModel<N, L>,
  kind: "node" | "link",
  index: number,
) {
  const nodes = new Set<number>(),
    links = new Set<number>();
  const edge = kind === "link" ? model.links[index] : undefined;
  const walk = (start: number, upstream: boolean) => {
    const seen = new Set<number>(),
      queue = [start];
    for (let head = 0; head < queue.length; head++) {
      const at = queue[head]!;
      if (seen.has(at)) continue;
      seen.add(at);
      nodes.add(at);
      for (const i of upstream
        ? model.nodes[at]!.sources
        : model.nodes[at]!.targets) {
        const link = model.links[i]!;
        if (!link.value) continue;
        links.add(i);
        queue.push(upstream ? link.source : link.target);
      }
    }
  };
  if (edge) {
    links.add(index);
    walk(edge.source, true);
    walk(edge.target, false);
  } else if (model.nodes[index]) {
    walk(index, true);
    walk(index, false);
  }
  return { nodes, links };
}

import type { FlowModel } from "./model";
export interface NodeGeometry {
  x: number;
  y: number;
  width: number;
  height: number;
  layer: number;
  labelX: number;
  labelY: number;
  labelWidth: number;
  last: boolean;
}
export interface LinkGeometry {
  path: string;
  centerPath: string;
  width: number;
  x: number;
  y: number;
  x0: number;
  x1: number;
  y0: number;
  y1: number;
}
export function layoutSankey<N, L>(
  model: FlowModel<N, L>,
  width: number,
  height: number,
  nodeWidth: number,
  gap: number,
  curvature: number,
  align: "justify" | "start",
) {
  const layers = model.nodes.map((n) =>
    align === "justify" && !n.targets.length && n.sources.length
      ? model.depth
      : n.depth,
  );
  const columns: number[][] = Array.from({ length: model.depth + 1 }, () => []);
  model.nodes.forEach((n, i) => columns[layers[i]!]!.push(n.index));
  const maxValue = model.nodes.reduce(
    (max, node) => Math.max(max, node.value),
    0,
  );
  // Normalize before summing columns to keep very large input values finite.
  const ratios = model.nodes.map((n) => (maxValue ? n.value / maxValue : 0));
  const long = model.links.filter(
    (l) => layers[l.target]! - layers[l.source]! > 1 && l.value > 0,
  );
  const longTotal = long.reduce((sum, l) => sum + l.value / maxValue, 0);
  const maxCount = columns.reduce((max, c) => Math.max(max, c.length), 1);
  const w = Math.max(
    width,
    nodeWidth + 178,
    model.depth * (260 + nodeWidth) + nodeWidth + 48,
  );
  const h = Math.max(height, 48 + maxCount * (48 + gap) + long.length * 12);
  const reserved = maxCount * 40 + Math.max(0, maxCount - 1) * gap;
  const available = Math.max(0, h - 48 - reserved - long.length * 12);
  const totals = columns.map((c) => c.reduce((sum, i) => sum + ratios[i]!, 0));
  const largest = totals.reduce((max, n) => Math.max(max, n), 0);
  const scale = largest + longTotal ? available / (largest + longTotal) : 0;
  const laneHeight = longTotal * scale + long.length * 12;
  const plotBottom = h - 24 - laneHeight;
  const nodes: NodeGeometry[] = Array(model.nodes.length);
  for (const [layer, column] of columns.entries()) {
    const used =
      totals[layer]! * scale +
      column.length * 40 +
      Math.max(0, column.length - 1) * gap;
    let y = 24 + (plotBottom - 24 - used) / 2;
    for (const index of column) {
      const nodeHeight = ratios[index]! * scale;
      const x = model.depth
        ? 24 + (layer * (w - 48 - nodeWidth)) / model.depth
        : 24;
      const last = model.depth > 0 && layer === model.depth;
      nodes[index] = {
        x,
        y: y + 20,
        width: nodeWidth,
        height: nodeHeight,
        layer,
        last,
        labelX: last ? x - 130 : x + nodeWidth + 10,
        labelY: y + 20 + nodeHeight / 2 - 19,
        labelWidth: 120,
      };
      y += nodeHeight + 40 + gap;
    }
  }
  const outgoing = new Map<number, number>(),
    incoming = new Map<number, number>();
  // Order attachment bands by the opposite node position, so a simple split/merge cannot cross itself.
  for (const node of model.nodes) {
    const g = nodes[node.index]!;
    for (const [indices, map, isSource, total] of [
      [node.targets, outgoing, true, node.outgoing],
      [node.sources, incoming, false, node.incoming],
    ] as const) {
      let offset =
        g.y + (g.height - (maxValue ? (total / maxValue) * scale : 0)) / 2;
      for (const index of [...indices].sort((a, b) => {
        const left = model.links[a]!,
          right = model.links[b]!;
        return (
          nodes[isSource ? left.target : left.source]!.y -
            nodes[isSource ? right.target : right.source]!.y || a - b
        );
      })) {
        map.set(index, offset);
        offset += maxValue ? (model.links[index]!.value / maxValue) * scale : 0;
      }
    }
  }
  let lane = plotBottom + 12;
  const links = model.links.map((edge): LinkGeometry => {
    const source = nodes[edge.source]!,
      target = nodes[edge.target]!;
    const thickness = maxValue ? (edge.value / maxValue) * scale : 0;
    const x0 = source.x + nodeWidth,
      x1 = target.x;
    const y0 = outgoing.get(edge.index)!,
      y1 = incoming.get(edge.index)!;
    const skip = target.layer - source.layer > 1 && thickness > 0;
    const laneY = lane;
    if (skip) lane += thickness + 12;
    const line = (offset: number, reverse = false) => {
      const a = y0 + offset,
        b = y1 + offset;
      if (skip) {
        const bend = Math.min(64, (x1 - x0) / 4),
          low = laneY + offset;
        return reverse
          ? `L ${x1} ${b} C ${x1 - bend} ${b} ${x1 - bend} ${low} ${x1 - bend * 2} ${low} H ${x0 + bend * 2} C ${x0 + bend} ${low} ${x0 + bend} ${a} ${x0} ${a}`
          : `M ${x0} ${a} C ${x0 + bend} ${a} ${x0 + bend} ${low} ${x0 + bend * 2} ${low} H ${x1 - bend * 2} C ${x1 - bend} ${low} ${x1 - bend} ${b} ${x1} ${b}`;
      }
      const bend = ((x1 - x0) * curvature) / 2;
      return reverse
        ? `L ${x1} ${b} C ${x1 - bend} ${b} ${x0 + bend} ${a} ${x0} ${a}`
        : `M ${x0} ${a} C ${x0 + bend} ${a} ${x1 - bend} ${b} ${x1} ${b}`;
    };
    return {
      path: thickness ? `${line(0)} ${line(thickness, true)} Z` : "",
      centerPath: line(thickness / 2),
      width: thickness,
      x: (x0 + x1) / 2,
      y: skip ? laneY + thickness / 2 : (y0 + y1 + thickness) / 2,
      x0,
      x1,
      y0,
      y1,
    };
  });
  return { nodes, links, width: w, height: h };
}
